package main
import("context";"errors";"io/fs";"iter";"os";"path";"path/filepath";"strings";"time"
"github.com/sonroyaalmerol/go-smb-server/smb/vfs")
type localBackend struct{root,realRoot string;upload,deletes,folders,hidden bool}
func newLocalBackend(root string,upload,deletes,folders,hidden bool)(*localBackend,error){abs,e:=filepath.Abs(root);if e!=nil{return nil,e};i,e:=os.Stat(abs);if e!=nil{return nil,e};if !i.IsDir(){return nil,fs.ErrInvalid};real,e:=filepath.EvalSymlinks(abs);if e!=nil{return nil,e};return &localBackend{filepath.Clean(abs),filepath.Clean(real),upload,deletes,folders,hidden},nil}
func within(root,p string)bool{r,e:=filepath.Rel(root,p);return e==nil&&!filepath.IsAbs(r)&&(r=="."||(r!=".."&&!strings.HasPrefix(r,".."+string(os.PathSeparator))))}
func(b *localBackend)resolve(input string)(string,error){clean:=path.Clean("/"+strings.ReplaceAll(input,"\\","/"));target:=filepath.Clean(filepath.Join(b.root,filepath.FromSlash(strings.TrimPrefix(clean,"/"))));if !within(b.root,target){return "",fs.ErrPermission};if _,e:=os.Lstat(target);e==nil{real,x:=filepath.EvalSymlinks(target);if x!=nil{return "",x};if !within(b.realRoot,filepath.Clean(real)){return "",fs.ErrPermission};return target,nil}else if !errors.Is(e,os.ErrNotExist){return "",e};parent:=filepath.Dir(target);for{if _,e:=os.Lstat(parent);e==nil{real,x:=filepath.EvalSymlinks(parent);if x!=nil{return "",x};if !within(b.realRoot,filepath.Clean(real)){return "",fs.ErrPermission};return target,nil}else if !errors.Is(e,os.ErrNotExist){return "",e};next:=filepath.Dir(parent);if next==parent{return "",fs.ErrPermission};parent=next}}
func(b *localBackend)Open(_ context.Context,o vfs.OpenOptions)(vfs.Handle,error){p,e:=b.resolve(o.Path);if e!=nil{return nil,e};if o.CreateDir{if !b.folders{return nil,fs.ErrPermission};if e=os.Mkdir(p,0755);e!=nil{return nil,e};f,e:=os.Open(p);if e!=nil{return nil,e};return &localHandle{b,f,p,o.Path},nil};info,se:=os.Stat(p);exists:=se==nil;if se!=nil&&!errors.Is(se,os.ErrNotExist){return nil,se};if exists&&info.IsDir(){f,e:=os.Open(p);if e!=nil{return nil,e};return &localHandle{b,f,p,o.Path},nil};switch o.Disposition{case vfs.DispositionOpen:if !exists{return nil,os.ErrNotExist};case vfs.DispositionCreate:if !b.upload{return nil,fs.ErrPermission};if exists{return nil,os.ErrExist};if e=createFile(p);e!=nil{return nil,e};case vfs.DispositionOpenIf:if !exists{if !b.upload{return nil,fs.ErrPermission};if e=createFile(p);e!=nil{return nil,e};};case vfs.DispositionSupersede,vfs.DispositionOverwrite,vfs.DispositionOverwriteIf:if !b.upload{return nil,fs.ErrPermission};if !exists&&o.Disposition==vfs.DispositionOverwrite{return nil,os.ErrNotExist};f,e:=os.OpenFile(p,os.O_CREATE|os.O_WRONLY|os.O_TRUNC,0644);if e!=nil{return nil,e};if e=f.Close();e!=nil{return nil,e};default:if !exists{return nil,os.ErrNotExist}};f,e:=os.Open(p);if e!=nil{return nil,e};return &localHandle{b,f,p,o.Path},nil}
func createFile(p string)error{f,e:=os.OpenFile(p,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0644);if e!=nil{return e};return f.Close()}
func(b *localBackend)Remove(_ context.Context,p string)error{if !b.deletes{return fs.ErrPermission};target,e:=b.resolve(p);if e!=nil{return e};if filepath.Clean(target)==b.root{return fs.ErrPermission};return os.RemoveAll(target)}
func(b *localBackend)Mkdir(_ context.Context,p string)error{if !b.folders{return fs.ErrPermission};target,e:=b.resolve(p);if e!=nil{return e};return os.Mkdir(target,0755)}
type localHandle struct{b *localBackend;f *os.File;p,relative string}
func(h *localHandle)Read(_ context.Context,o int64,p []byte)(int,error){return h.f.ReadAt(p,o)}
func(h *localHandle)Write(_ context.Context,o int64,p []byte)(int,error){if !h.b.upload{return 0,fs.ErrPermission};target,e:=h.b.resolve(h.relative);if e!=nil{return 0,e};f,e:=os.OpenFile(target,os.O_WRONLY,0);if e!=nil{return 0,e};defer f.Close();return f.WriteAt(p,o)}
func(h *localHandle)Close(_ context.Context)error{return h.f.Close()}
func(h *localHandle)Stat(_ context.Context)(vfs.FileInfo,error){i,e:=os.Stat(h.p);if e!=nil{return vfs.FileInfo{},e};return infoOf(filepath.Base(h.p),i),nil}
func(h *localHandle)Enumerate(_ context.Context,pattern string)iter.Seq2[vfs.FileInfo,error]{return func(yield func(vfs.FileInfo,error) bool){entries,e:=os.ReadDir(h.p);if e!=nil{yield(vfs.FileInfo{},e);return};for _,item:=range entries{name:=item.Name();if !h.b.hidden&&strings.HasPrefix(name,"."){continue};if pattern!=""{ok,x:=path.Match(strings.ToLower(pattern),strings.ToLower(name));if x!=nil{yield(vfs.FileInfo{},x);return};if !ok{continue}};i,x:=item.Info();if x!=nil{continue};if !yield(infoOf(name,i),nil){return}}}}
func infoOf(name string,i os.FileInfo)vfs.FileInfo{now:=time.Now();a:=uint32(0x80);if i.IsDir(){a=0x10};if strings.HasPrefix(name,"."){a|=0x02};return vfs.FileInfo{Name:name,Size:i.Size(),IsDir:i.IsDir(),Attributes:a,CreationTime:i.ModTime(),LastAccess:i.ModTime(),LastWrite:i.ModTime(),ChangeTime:now}}
func(h *localHandle)SetInfo(_ context.Context,r *vfs.SetInfoRequest)error{if !h.b.upload{return fs.ErrPermission};p,e:=h.b.resolve(h.relative);if e!=nil{return e};if r.EndOfFile!=nil{if *r.EndOfFile<0{return fs.ErrInvalid};if e=os.Truncate(p,*r.EndOfFile);e!=nil{return e}};if r.LastAccessTime!=nil||r.LastWriteTime!=nil{i,e:=os.Stat(p);if e!=nil{return e};a,m:=i.ModTime(),i.ModTime();if r.LastAccessTime!=nil{a=*r.LastAccessTime};if r.LastWriteTime!=nil{m=*r.LastWriteTime};if e=os.Chtimes(p,a,m);e!=nil{return e}};return nil}
func(h *localHandle)Rename(_ context.Context,newPath string,replace bool)error{if !h.b.upload||!h.b.deletes{return fs.ErrPermission};base:=filepath.Base(filepath.FromSlash(strings.ReplaceAll(newPath,"\\","/")));if base=="."||base==string(os.PathSeparator)||base==""{return fs.ErrInvalid};rel:=filepath.ToSlash(filepath.Join(filepath.Dir(h.relative),base));target,e:=h.b.resolve(rel);if e!=nil{return e};if !replace{if _,e=os.Lstat(target);e==nil{return os.ErrExist}};if e=os.Rename(h.p,target);e!=nil{return e};h.p=target;h.relative=rel;return nil}
